//! Verifies the Rust mappers against `contracts/fixtures/metadata/expected.json` (generated by the JS reference mapper).

use std::path::PathBuf;

use serde_json::{Value, json};
use tk_core::metadata::mapping::*;

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../../contracts/fixtures/metadata")
}

fn read(name: &str) -> Value {
    let text = std::fs::read_to_string(dir().join(name)).unwrap_or_else(|e| panic!("{name}: {e}"));
    serde_json::from_str(&text).unwrap()
}

fn expected(key: &str) -> Value {
    read("expected.json")[key].clone()
}

fn page_json(p: &tk_core::FeedPage) -> Value {
    serde_json::to_value(p).unwrap()
}

#[test]
fn anilist_trending_and_search_pages_match_expected() {
    for f in ["anilist-trending-page.json", "anilist-search-page.json"] {
        let page = map_anilist_page(&read(f)).unwrap();
        assert_eq!(page_json(&page), expected(f), "{f}");
    }
}

#[test]
fn anizip_ids_and_episodes_match_expected() {
    let raw = read("anizip-frieren.json");
    let got = json!({ "ids": map_anizip_ids(&raw), "episodes": map_anizip_episodes(&raw) });
    assert_eq!(got, expected("anizip-frieren.json"));
}

#[test]
fn kitsu_list_and_episodes_match_expected() {
    let doc = read("kitsu-anime-list.json");
    let (items, has_next) = map_kitsu_list(&doc);
    assert_eq!(json!({ "items": items, "hasNext": has_next }), expected("kitsu-anime-list.json"));

    let eps = map_kitsu_episodes(&read("kitsu-episodes.json"));
    assert_eq!(json!({ "episodes": eps }), expected("kitsu-episodes.json"));
}

#[test]
fn kitsu_detail_resource_maps() {
    let doc = read("kitsu-anime-detail.json");
    let res = if doc["data"].is_array() { doc["data"][0].clone() } else { doc["data"].clone() };
    let m = map_kitsu_media(&doc, &res);
    assert_eq!(m.source_provider, "kitsu");
    assert!(m.media_ref.kitsu_id.is_some());
    assert!(!m.title.is_empty());
}

#[test]
fn rate_limited_body_is_an_error_not_an_empty_page() {
    let fx = read("anilist-rate-limited.json");
    assert_eq!(fx["httpStatus"], 429);
    let err = map_anilist_page(&fx["body"]).unwrap_err();
    // the provider turns HTTP 429 into RateLimited before the mapper; the mapper must never yield "no results"
    assert!(matches!(err, tk_core::ProviderError::Parse(_)));
    assert_eq!(expected("anilist-rate-limited.json")["error"]["cooldownSeconds"], 60);
    assert_eq!(tk_core::metadata::COOLDOWN.as_secs(), 60);
    assert!(tk_core::ProviderError::RateLimited { provider: "anilist".into() }.trips_cooldown());
}
